<form class="panel grid" method="post" action="<?= $url('save/kegiatan') ?>"><?= $token ?><input type="hidden" name="id" value="<?= $esc($k['id_kegiatan']) ?>">
<label>Tahun<input required type="number" name="tahun" min="2000" max="2100" value="<?= $esc($k['tahun']) ?>" <?= $k['id_kegiatan']?'readonly':'' ?>></label><label>OPD<select required name="id_opd_pemkab"><option value="">Pilih OPD</option><?php foreach($opds as $o): ?><option value="<?= $o['id_opd_pemkab'] ?>" <?= ($k['id_opd_pemkab']??0)==$o['id_opd_pemkab']?'selected':'' ?>><?= $esc($o['nama_opd']) ?></option><?php endforeach; ?></select></label><label>Status kontrak<select name="st_kontrak"><?php foreach(['B'=>'Belum','P'=>'Proses','S'=>'Selesai'] as $v=>$n): ?><option value="<?= $v ?>" <?= $k['st_kontrak']===$v?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label>
<label class="full">Nama kegiatan<input required name="keperluan" maxlength="255" value="<?= $esc($k['keperluan']??'') ?>"></label>
<?php foreach(['pagu'=>'Pagu (Rp)','nilai'=>'Nilai kontrak (Rp)'] as $f=>$label): ?><label><?= $label ?><input required type="number" min="0" step="0.01" name="<?= $f ?>" value="<?= $esc($k[$f]) ?>"></label><?php endforeach; ?>
<label>Tanggal kontrak<input type="date" name="tgl_kontrak" value="<?= $esc($k['tgl_kontrak']??'') ?>"></label>
<?php foreach(['waktu'=>'Waktu pelaksanaan','lokasi_pekerjaan'=>'Lokasi pekerjaan','koordinat'=>'Koordinat'] as $f=>$label): ?><label><?= $label ?><input name="<?= $f ?>" maxlength="<?= $f==='koordinat'?75:150 ?>" value="<?= $esc($k[$f]??'') ?>"></label><?php endforeach; ?>
<?php foreach(['psd'=>'Dukungan PSD','phtc'=>'Dukungan PHTC'] as $f=>$label): ?><label><?= $label ?><select name="<?= $f ?>"><option value="">Tidak dipetakan</option><?php foreach($references as $ref)if($ref['jenis']===$f): ?><option value="<?= $esc($ref['kode']) ?>" <?= ($k[$f]??'')===$ref['kode']?'selected':'' ?>><?= $esc($ref['nama']) ?></option><?php endif; ?></select><small>Referensi diambil dari pusat melalui CLI.</small></label><?php endforeach; ?>
<div class="full checkgroup"><?php foreach(['status_1'=>'BKP','status_3'=>'Infrastruktur','tkd'=>'Tambahan TKD'] as $f=>$label): ?><label><input type="checkbox" name="<?= $f ?>" value="Y" <?= ($k[$f]??'N')==='Y'?'checked':'' ?>><?= $label ?></label><?php endforeach; ?></div><div class="full actions"><button>Simpan kegiatan</button><a class="button secondary" href="<?= $url() ?>">Kembali</a></div></form>
